def normalize_question(value: str) -> str:
    text = str(value or "").casefold()
    text = re.sub(r"<[^>]+>", " ", text)
    text = re.sub(r"\[[^\]]+\]", " ", text)
    text = re.sub(r"[^a-z0-9]+", " ", text)
    tokens = re.sub(r"\s+", " ", text).strip().split()
    tokens = [
        token[:-1] if len(token) > 4 and token.endswith("s") and not token.endswith(("ss", "us", "is")) else token
        for token in tokens
    ]
    tokens = ["end" if token == "stop" else token for token in tokens]
    return " ".join(tokens)


def search_patterns(domain: str | None = None, variable_name: str | None = None) -> list[dict[str, Any]]:
    domain = domain.upper() if domain else None
    variable_name = variable_name.upper() if variable_name else None
    return [
        row
        for row in VARIABLE_QUESTION_PATTERNS
        if (domain is None or row["domain"] == domain)
        and (variable_name is None or row["variable_name"] == variable_name)
    ]


def _score_pattern(query: str, query_tokens: set[str], row: dict[str, Any]) -> tuple[float, list[str]]:
    rule = row["normalized_question"]
    rule_tokens = set(row["tokens"])
    if not query_tokens or not rule_tokens:
        return 0.0, []

    variable_name = str(row.get("variable_name", ""))
    if variable_name.endswith("DTC") and not re.search(r"\b(date|time|datetime|performed|collected|collection|obtained|assessment)\b", query):
        return 0.0, []
    if variable_name.endswith("STAT") and not re.search(r"\b(done|not done|performed|collected|assessed|available|status|obtained|completed)\b", query):
        return 0.0, []
    if variable_name.endswith(("REASND", "REASOC")) and not re.search(r"\b(reason|why|not done|not performed|not collected|not available)\b", query):
        return 0.0, []
    date_time_only_terms = set(("start", "stop", "end", "onset", "date", "time", "datetime", "collection", "collected"))
    if query_tokens and query_tokens <= date_time_only_terms and not variable_name.endswith(("DTC", "DY", "TPT", "TPTNUM", "ELTM")):
        return 0.0, []

    matched_terms = sorted(query_tokens & rule_tokens)
    overlap_rule = len(matched_terms) / len(rule_tokens)
    overlap_query = len(matched_terms) / len(query_tokens)
    fuzzy = SequenceMatcher(None, query, rule).ratio()

    if query == rule:
        return 1.0, matched_terms

    if len(rule_tokens) >= 2 and re.search(rf"\b{re.escape(rule)}\b", query):
        return max(0.94, fuzzy), matched_terms

    if len(query_tokens) >= 2 and re.search(rf"\b{re.escape(query)}\b", rule):
        return max(0.9, fuzzy), matched_terms

    generic_single_terms = ('date', 'time', 'result', 'value', 'unit', 'other', 'specify', 'test', 'code', 'number', 'id')
    if (
        len(matched_terms) == 1
        and len(query_tokens) == 1
        and len(matched_terms[0]) >= 4
        and matched_terms[0] not in generic_single_terms
    ):
        return 0.86, matched_terms

    if len(matched_terms) < 2:
        return 0.0, matched_terms

    score = (0.6 * overlap_rule) + (0.25 * overlap_query) + (0.15 * fuzzy)
    return round(score, 4), matched_terms


def match_variable_question_patterns(
    domain: str,
    question: str,
    min_score: float = 0.82,
) -> list[dict[str, Any]]:
    domain = str(domain or "").upper()
    query = normalize_question(question)
    query_tokens = set(query.split())
    matches = []

    for row in VARIABLE_QUESTION_PATTERNS:
        if row["domain"] != domain:
            continue
        score, matched_terms = _score_pattern(query, query_tokens, row)
        if score >= min_score:
            matches.append({**row, "score": score, "matched_terms": matched_terms})

    return sorted(
        matches,
        key=lambda row: (row["score"], row["supporting_crf_count"], row["row_count"]),
        reverse=True,
    )
